/**
 * Typed multi- or single-select faceted filter for a DataTable column.
 *
 * @package @edbn/ui
 * @version 0.3.0
 * @since 0.3.0
 * @registryPartOf data-table
 */

"use client";

import * as React from "react";
import {
  Check,
  MagnifyingGlass,
  SlidersHorizontal,
  X,
} from "@phosphor-icons/react";
import type { Column } from "@tanstack/react-table";
import {
  PopoverPopup,
  PopoverPortal,
  PopoverPositioner,
  PopoverRoot,
  PopoverTitle,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import type { DataTableFilterOption } from "./data-table-types";

export interface DataTableFacetedFilterProps<TData, TValue> extends Omit<
  React.ComponentPropsWithRef<"button">,
  "children" | "onChange" | "title" | "value"
> {
  column: Column<TData, TValue>;
  title: string;
  options: readonly DataTableFilterOption<TValue>[];
  /** Store an array of values when true, or one value when false. @default true */
  multiple?: boolean;
  /** Show local option search. Defaults to true for more than seven options. */
  searchable?: boolean;
  /** Maximum option rows rendered after local filtering. @default 100 */
  maxVisibleOptions?: number;
  /** Message shown when no options match local search. */
  emptyContent?: React.ReactNode;
}

function DataTableFacetedFilterImpl<TData, TValue>(
  {
    column,
    title,
    options,
    multiple = true,
    searchable = options.length > 7,
    maxVisibleOptions = 100,
    emptyContent = "No options found.",
    className,
    disabled,
    ...triggerProps
  }: Omit<DataTableFacetedFilterProps<TData, TValue>, "ref">,
  ref: React.ForwardedRef<HTMLButtonElement>
) {
  const radioGroupName = React.useId();
  const [open, setOpen] = React.useState(false);
  const [query, setQuery] = React.useState("");
  const rawValue = column.getFilterValue();
  const selectedValues = new Set<TValue>(
    Array.isArray(rawValue)
      ? (rawValue as TValue[])
      : rawValue == null
        ? []
        : [rawValue as TValue]
  );
  const selectedCount = selectedValues.size;
  const facetedCounts = column.getFacetedUniqueValues();
  const normalizedQuery = query.trim().toLocaleLowerCase();
  const safeMaxVisibleOptions = Number.isFinite(maxVisibleOptions)
    ? Math.max(1, Math.floor(maxVisibleOptions))
    : 100;
  const visibleOptions = options
    .filter((option) => {
      if (!normalizedQuery) return true;
      const optionText =
        option.searchText ??
        (typeof option.label === "string"
          ? option.label
          : String(option.value));
      return optionText.toLocaleLowerCase().includes(normalizedQuery);
    })
    .slice(0, safeMaxVisibleOptions);

  const updateOption = (option: DataTableFilterOption<TValue>) => {
    if (option.disabled) return;

    if (!multiple) {
      column.setFilterValue(option.value);
      setOpen(false);
      return;
    }

    const nextValues = new Set(selectedValues);
    if (nextValues.has(option.value)) nextValues.delete(option.value);
    else nextValues.add(option.value);
    column.setFilterValue(nextValues.size ? Array.from(nextValues) : undefined);
  };

  const clear = () => {
    column.setFilterValue(undefined);
    setQuery("");
  };

  return (
    <PopoverRoot
      open={open}
      onOpenChange={(nextOpen) => {
        setOpen(nextOpen);
        if (!nextOpen) setQuery("");
      }}
    >
      <PopoverTrigger
        ref={ref}
        type="button"
        aria-label={`Filter by ${title}`}
        disabled={disabled || !column.getCanFilter()}
        data-slot="data-table-faceted-filter-trigger"
        className={cn(
          "inline-flex h-9 items-center gap-2 rounded-md border border-dashed border-border bg-background px-3 text-sm font-medium shadow-xs",
          "hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
          "disabled:pointer-events-none disabled:opacity-50",
          className
        )}
        {...triggerProps}
      >
        <SlidersHorizontal aria-hidden className="size-3.5" weight="bold" />
        <span className="max-w-36 truncate">{title}</span>
        {selectedCount > 0 ? (
          <span className="inline-flex min-w-5 items-center justify-center rounded-full bg-muted px-1.5 text-xs tabular-nums text-muted-foreground">
            {selectedCount}
          </span>
        ) : null}
      </PopoverTrigger>
      <PopoverPortal>
        <PopoverPositioner sideOffset={6} align="start">
          <PopoverPopup className="w-64 p-1.5">
            <PopoverTitle className="sr-only">Filter by {title}</PopoverTitle>
            {searchable ? (
              <div className="relative mb-1">
                <MagnifyingGlass
                  aria-hidden
                  className="pointer-events-none absolute start-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground"
                  weight="bold"
                />
                <input
                  type="search"
                  aria-label={`Search ${title} options`}
                  autoComplete="off"
                  value={query}
                  placeholder="Search options…"
                  className={cn(
                    "h-8 w-full rounded-md border border-input bg-transparent pe-8 ps-8 text-sm outline-none",
                    "placeholder:text-muted-foreground focus-visible:ring-1 focus-visible:ring-ring",
                    "[&::-webkit-search-cancel-button]:hidden"
                  )}
                  onChange={(event) => setQuery(event.currentTarget.value)}
                />
                {query ? (
                  <button
                    type="button"
                    aria-label="Clear option search"
                    className="absolute end-1 top-1/2 inline-flex size-6 -translate-y-1/2 items-center justify-center rounded text-muted-foreground hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring"
                    onClick={() => setQuery("")}
                  >
                    <X aria-hidden className="size-3" weight="bold" />
                  </button>
                ) : null}
              </div>
            ) : null}
            <div
              role={multiple ? "group" : "radiogroup"}
              aria-label={`${title} filter options`}
              className="max-h-72 overflow-y-auto overscroll-contain"
            >
              {visibleOptions.length ? (
                visibleOptions.map((option, index) => {
                  const selected = selectedValues.has(option.value);
                  const count = option.count ?? facetedCounts.get(option.value);
                  const OptionIcon = option.icon;
                  const optionContent = (
                    <>
                      <span
                        aria-hidden="true"
                        className={cn(
                          "inline-flex size-4 shrink-0 items-center justify-center border border-border",
                          multiple ? "rounded-sm" : "rounded-full",
                          selected &&
                            "border-primary bg-primary text-primary-foreground"
                        )}
                      >
                        {selected ? (
                          <Check
                            aria-hidden
                            className="size-3"
                            weight="bold"
                          />
                        ) : null}
                      </span>
                      {OptionIcon ? (
                        <OptionIcon
                          aria-hidden="true"
                          className="size-4 shrink-0 text-muted-foreground"
                        />
                      ) : null}
                      <span className="min-w-0 flex-1 truncate">
                        {option.label}
                      </span>
                      {typeof count === "number" ? (
                        <span className="ms-auto text-xs tabular-nums text-muted-foreground">
                          {count.toLocaleString()}
                        </span>
                      ) : null}
                    </>
                  );

                  if (!multiple) {
                    return (
                      <label
                        key={`${String(option.value)}-${index}`}
                        className={cn(
                          "flex min-h-9 w-full items-center gap-2 rounded-md px-2 text-start text-sm outline-none",
                          "hover:bg-muted has-[:focus-visible]:bg-muted has-[:focus-visible]:ring-1 has-[:focus-visible]:ring-ring",
                          "has-[:disabled]:pointer-events-none has-[:disabled]:opacity-50"
                        )}
                      >
                        <input
                          type="radio"
                          name={radioGroupName}
                          value={String(index)}
                          checked={selected}
                          disabled={option.disabled}
                          className="sr-only"
                          onChange={() => updateOption(option)}
                        />
                        {optionContent}
                      </label>
                    );
                  }

                  return (
                    <button
                      key={`${String(option.value)}-${index}`}
                      type="button"
                      role="checkbox"
                      aria-checked={selected}
                      disabled={option.disabled}
                      className={cn(
                        "flex min-h-9 w-full items-center gap-2 rounded-md px-2 text-start text-sm outline-none",
                        "hover:bg-muted focus-visible:bg-muted focus-visible:ring-1 focus-visible:ring-ring",
                        "disabled:pointer-events-none disabled:opacity-50"
                      )}
                      onClick={() => updateOption(option)}
                    >
                      {optionContent}
                    </button>
                  );
                })
              ) : (
                <div className="px-3 py-6 text-center text-sm text-muted-foreground">
                  {emptyContent}
                </div>
              )}
            </div>
            {selectedCount > 0 ? (
              <div className="mt-1 border-t border-border pt-1">
                <button
                  type="button"
                  className="flex h-8 w-full items-center justify-center rounded-md text-sm text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
                  onClick={clear}
                >
                  Clear filter
                </button>
              </div>
            ) : null}
          </PopoverPopup>
        </PopoverPositioner>
      </PopoverPortal>
    </PopoverRoot>
  );
}

type DataTableFacetedFilterComponent = {
  <TData, TValue>(
    props: DataTableFacetedFilterProps<TData, TValue>
  ): React.ReactElement | null;
  displayName?: string;
};

const DataTableFacetedFilter = React.forwardRef(
  DataTableFacetedFilterImpl
) as DataTableFacetedFilterComponent;
DataTableFacetedFilter.displayName = "DataTableFacetedFilter";

export { DataTableFacetedFilter };

/**
 * Accessible client- and manual-pagination controls for DataTable.
 *
 * @package @edbn/ui
 * @version 0.3.0
 * @since 0.3.0
 * @registryPartOf data-table
 */

"use client";

import * as React from "react";
import {
  CaretDoubleLeft,
  CaretDoubleRight,
  CaretLeft,
  CaretRight,
} from "@phosphor-icons/react";
import type { Table } from "@tanstack/react-table";
import { cn } from "@/lib/utils";

export interface DataTablePaginationProps<
  TData,
> extends React.ComponentPropsWithRef<"nav"> {
  table: Table<TData>;
  /** Available page sizes. @default [10, 20, 30, 50, 100] */
  pageSizeOptions?: readonly number[];
  /** Show the page-size selector. @default true */
  showPageSize?: boolean;
  /** Show selected row feedback. @default true */
  showSelectedCount?: boolean;
  /** Show first and last page buttons. @default true */
  showBoundaryButtons?: boolean;
  /** Override previous-page availability for cursor/manual pagination. */
  canPreviousPage?: boolean;
  /** Override next-page availability for cursor/manual pagination. */
  canNextPage?: boolean;
  /** Override selection feedback for off-page server selection. */
  selectedCount?: number;
}

function DataTablePaginationImpl<TData>(
  {
    table,
    pageSizeOptions = [10, 20, 30, 50, 100],
    showPageSize = true,
    showSelectedCount = true,
    showBoundaryButtons = true,
    canPreviousPage,
    canNextPage,
    selectedCount: selectedCountProp,
    className,
    "aria-label": ariaLabel = "Table pagination",
    ...props
  }: Omit<DataTablePaginationProps<TData>, "ref">,
  ref: React.ForwardedRef<HTMLElement>
) {
  const { pageIndex, pageSize } = table.getState().pagination;
  const rawPageCount = table.getPageCount();
  const hasKnownPageCount = Number.isFinite(rawPageCount) && rawPageCount >= 0;
  const pageCount = hasKnownPageCount ? Math.floor(rawPageCount) : -1;
  const safePageIndex = Number.isFinite(pageIndex)
    ? Math.max(0, Math.floor(pageIndex))
    : 0;
  const displayPage =
    hasKnownPageCount && pageCount === 0 ? 0 : safePageIndex + 1;
  const rawSelectedCount =
    selectedCountProp ?? table.getFilteredSelectedRowModel().rows.length;
  const selectedCount = Number.isFinite(rawSelectedCount)
    ? Math.max(0, Math.floor(rawSelectedCount))
    : 0;
  const hasPreviousPage = canPreviousPage ?? table.getCanPreviousPage();
  const hasNextPage = canNextPage ?? table.getCanNextPage();
  const normalizedPageSizes = Array.from(
    new Set(
      [...pageSizeOptions, pageSize]
        .filter((size) => Number.isFinite(size) && size > 0)
        .map((size) => Math.floor(size))
    )
  ).sort((a, b) => a - b);

  return (
    <nav
      ref={ref}
      aria-label={ariaLabel}
      data-slot="data-table-pagination"
      className={cn(
        "flex min-w-0 flex-wrap items-center gap-x-4 gap-y-2",
        className
      )}
      {...props}
    >
      {showSelectedCount ? (
        <p
          className="min-w-0 flex-1 text-xs text-muted-foreground"
          aria-live="polite"
        >
          {selectedCount > 0
            ? `${selectedCount.toLocaleString()} row${selectedCount === 1 ? "" : "s"} selected`
            : "No rows selected"}
        </p>
      ) : (
        <span className="flex-1" />
      )}

      {showPageSize ? (
        <label className="flex items-center gap-2 text-xs text-muted-foreground">
          <span className="hidden sm:inline">Rows per page</span>
          <span className="sr-only sm:hidden">Rows per page</span>
          <select
            value={pageSize}
            className={cn(
              "h-9 rounded-md border border-border bg-background px-2 text-sm text-foreground shadow-xs",
              "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            )}
            onChange={(event) => table.setPageSize(Number(event.target.value))}
          >
            {normalizedPageSizes.map((size) => (
              <option key={size} value={size}>
                {size}
              </option>
            ))}
          </select>
        </label>
      ) : null}

      <p
        aria-live="polite"
        aria-atomic="true"
        className="min-w-20 text-center text-xs font-medium tabular-nums text-muted-foreground"
      >
        Page {displayPage}
        {hasKnownPageCount ? ` of ${pageCount}` : ""}
      </p>

      <div className="flex items-center gap-1">
        {showBoundaryButtons ? (
          <PaginationButton
            aria-label="Go to first page"
            disabled={!hasPreviousPage}
            onClick={() => table.firstPage()}
          >
            <CaretDoubleLeft
              aria-hidden
              className="size-4 rtl:rotate-180"
              weight="bold"
            />
          </PaginationButton>
        ) : null}
        <PaginationButton
          aria-label="Go to previous page"
          disabled={!hasPreviousPage}
          onClick={() => table.previousPage()}
        >
          <CaretLeft
            aria-hidden
            className="size-4 rtl:rotate-180"
            weight="bold"
          />
        </PaginationButton>
        <PaginationButton
          aria-label="Go to next page"
          disabled={!hasNextPage}
          onClick={() => table.nextPage()}
        >
          <CaretRight
            aria-hidden
            className="size-4 rtl:rotate-180"
            weight="bold"
          />
        </PaginationButton>
        {showBoundaryButtons ? (
          <PaginationButton
            aria-label="Go to last page"
            disabled={!hasKnownPageCount || !hasNextPage}
            onClick={() => table.lastPage()}
          >
            <CaretDoubleRight
              aria-hidden
              className="size-4 rtl:rotate-180"
              weight="bold"
            />
          </PaginationButton>
        ) : null}
      </div>
    </nav>
  );
}

type DataTablePaginationComponent = {
  <TData>(props: DataTablePaginationProps<TData>): React.ReactElement | null;
  displayName?: string;
};

const DataTablePagination = React.forwardRef(
  DataTablePaginationImpl
) as DataTablePaginationComponent;
DataTablePagination.displayName = "DataTablePagination";

function PaginationButton({
  className,
  ...props
}: React.ComponentPropsWithoutRef<"button">) {
  return (
    <button
      type="button"
      className={cn(
        "inline-flex size-9 items-center justify-center rounded-md border border-border bg-background shadow-xs",
        "hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        "disabled:pointer-events-none disabled:opacity-40",
        className
      )}
      {...props}
    />
  );
}

export { DataTablePagination };

/**
 * Pointer, touch, and keyboard column-resize handle for DataTable.
 *
 * @package @edbn/ui
 * @version 0.3.0
 * @since 0.3.0
 * @registryPartOf data-table
 */

"use client";

import * as React from "react";
import type { Column, Header, Table } from "@tanstack/react-table";

import { cn } from "@/lib/utils";

const ACCESSIBLE_UNBOUNDED_COLUMN_MAX = 1000;

type ResizeStart = {
  pointerId: number;
  clientX: number;
  logicalDelta: number;
  sizes: Array<{ id: string; size: number; min: number; max: number }>;
};

function getColumnBounds<TData>(column: Column<TData, unknown>) {
  const rawMinimum = column.columnDef.minSize;
  const rawMaximum = column.columnDef.maxSize;
  const min =
    rawMinimum != null && Number.isFinite(rawMinimum)
      ? Math.max(0, rawMinimum)
      : 20;
  const max =
    rawMaximum != null && Number.isFinite(rawMaximum)
      ? Math.max(min, rawMaximum)
      : Number.MAX_SAFE_INTEGER;
  return { min, max };
}

export interface DataTableResizeHandleProps<TData, TValue> extends Omit<
  React.ComponentPropsWithRef<"div">,
  | "onDoubleClick"
  | "onKeyDown"
  | "onPointerCancel"
  | "onPointerDown"
  | "onPointerMove"
  | "onPointerUp"
> {
  table: Table<TData>;
  header: Header<TData, TValue>;
  /** Keyboard resize increment in pixels. @default 8 */
  step?: number;
  /** Shift-modified keyboard increment in pixels. @default 24 */
  largeStep?: number;
  /** Accessible separator name. Defaults to the column id. */
  label?: string;
  onDoubleClick?: React.MouseEventHandler<HTMLDivElement>;
  onKeyDown?: React.KeyboardEventHandler<HTMLDivElement>;
  onPointerCancel?: React.PointerEventHandler<HTMLDivElement>;
  onPointerDown?: React.PointerEventHandler<HTMLDivElement>;
  onPointerMove?: React.PointerEventHandler<HTMLDivElement>;
  onPointerUp?: React.PointerEventHandler<HTMLDivElement>;
}

function DataTableResizeHandleImpl<TData, TValue>(
  {
    table,
    header,
    step = 8,
    largeStep = 24,
    label = `Resize ${header.column.id} column`,
    className,
    style,
    onDoubleClick,
    onKeyDown,
    onPointerCancel,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    ...props
  }: Omit<DataTableResizeHandleProps<TData, TValue>, "ref">,
  ref: React.ForwardedRef<HTMLDivElement>
) {
  const dragRef = React.useRef<ResizeStart | null>(null);
  const canResize = header.column.getCanResize();
  const isResizing = header.column.getIsResizing();
  const safeStep = Number.isFinite(step) && step > 0 ? step : 8;
  const safeLargeStep =
    Number.isFinite(largeStep) && largeStep > 0 ? largeStep : 24;
  const leafColumns = header
    .getLeafHeaders()
    .filter((leaf) => leaf.subHeaders.length === 0)
    .map((leaf) => leaf.column);
  const minimumSize = leafColumns.reduce(
    (sum, column) => sum + getColumnBounds(column).min,
    0
  );
  const maximumSize = leafColumns.reduce((sum, column) => {
    const maximum = getColumnBounds(column).max;
    return (
      sum +
      (maximum === Number.MAX_SAFE_INTEGER
        ? Math.max(column.getSize(), ACCESSIBLE_UNBOUNDED_COLUMN_MAX)
        : maximum)
    );
  }, 0);
  const resizeDirection =
    table.options.columnResizeDirection === "rtl" ? -1 : 1;
  const sizingInfo = table.getState().columnSizingInfo;
  const visualOffset =
    isResizing && table.options.columnResizeMode === "onEnd"
      ? (sizingInfo.deltaOffset ?? 0) * resizeDirection
      : 0;

  React.useEffect(
    () => () => {
      if (dragRef.current) {
        table.setColumnSizingInfo((old) => ({
          ...old,
          columnSizingStart: [],
          deltaOffset: null,
          deltaPercentage: null,
          isResizingColumn: false,
          startOffset: null,
          startSize: null,
        }));
      }
    },
    [table]
  );

  const getNextSizes = React.useCallback(
    (start: ResizeStart, delta: number) => {
      const total = start.sizes.reduce((sum, item) => sum + item.size, 0);
      const percentage = total > 0 ? delta / total : 0;
      return start.sizes.map((item) => ({
        ...item,
        size: Math.min(
          item.max,
          Math.max(
            item.min,
            Math.round((item.size + item.size * percentage) * 100) / 100
          )
        ),
      }));
    },
    []
  );

  const commitSizes = React.useCallback(
    (sizes: ResizeStart["sizes"]) => {
      table.setColumnSizing((old) => ({
        ...old,
        ...Object.fromEntries(sizes.map((item) => [item.id, item.size])),
      }));
    },
    [table]
  );

  const updateDrag = (clientX: number, commit: boolean) => {
    const start = dragRef.current;
    if (!start) return;
    const logicalDelta = (clientX - start.clientX) * resizeDirection;
    start.logicalDelta = logicalDelta;
    const nextSizes = getNextSizes(start, logicalDelta);

    table.setColumnSizingInfo((old) => ({
      ...old,
      deltaOffset: logicalDelta,
      deltaPercentage:
        header.getSize() > 0 ? logicalDelta / header.getSize() : 0,
    }));

    if (commit || table.options.columnResizeMode === "onChange") {
      commitSizes(nextSizes);
    }
  };

  const finishDrag = (
    event: React.PointerEvent<HTMLDivElement>,
    cancelled: boolean
  ) => {
    const start = dragRef.current;
    if (!start || start.pointerId !== event.pointerId) return;

    if (cancelled && table.options.columnResizeMode === "onChange") {
      commitSizes(start.sizes);
    } else if (!cancelled) {
      updateDrag(event.clientX, true);
    }

    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    dragRef.current = null;
    table.setColumnSizingInfo((old) => ({
      ...old,
      columnSizingStart: [],
      deltaOffset: null,
      deltaPercentage: null,
      isResizingColumn: false,
      startOffset: null,
      startSize: null,
    }));
  };

  const resizeBy = (delta: number) => {
    const currentSizes = leafColumns.map((column) => ({
      id: column.id,
      size: column.getSize(),
      ...getColumnBounds(column),
    }));
    commitSizes(
      getNextSizes(
        {
          pointerId: -1,
          clientX: 0,
          logicalDelta: 0,
          sizes: currentSizes,
        },
        delta
      )
    );
  };

  return (
    <div
      {...props}
      ref={ref}
      role="separator"
      aria-label={label}
      aria-orientation="vertical"
      aria-valuemin={Math.round(minimumSize)}
      aria-valuemax={Math.round(maximumSize)}
      aria-valuenow={Math.round(header.getSize())}
      tabIndex={canResize ? 0 : -1}
      data-slot="data-table-resize-handle"
      data-resizing={isResizing ? "" : undefined}
      className={cn(
        "absolute inset-y-0 -end-3 z-10 w-6 cursor-col-resize touch-none select-none",
        "after:absolute after:inset-y-1 after:start-1/2 after:w-px after:-translate-x-1/2 after:bg-border",
        "hover:after:w-0.5 hover:after:bg-primary focus-visible:outline-none focus-visible:after:w-0.5 focus-visible:after:bg-ring",
        "data-[resizing]:after:w-0.5 data-[resizing]:after:bg-primary",
        !canResize && "pointer-events-none hidden",
        className
      )}
      style={{ transform: `translateX(${visualOffset}px)`, ...style }}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (event.defaultPrevented || !canResize || dragRef.current) return;
        if (event.pointerType === "mouse" && event.button !== 0) return;

        event.preventDefault();
        event.currentTarget.setPointerCapture(event.pointerId);
        const sizes = leafColumns.map((column) => ({
          id: column.id,
          size: column.getSize(),
          ...getColumnBounds(column),
        }));
        dragRef.current = {
          pointerId: event.pointerId,
          clientX: event.clientX,
          logicalDelta: 0,
          sizes,
        };
        table.setColumnSizingInfo((old) => ({
          ...old,
          columnSizingStart: sizes.map((item) => [item.id, item.size]),
          deltaOffset: 0,
          deltaPercentage: 0,
          isResizingColumn: header.column.id,
          startOffset: event.clientX,
          startSize: header.getSize(),
        }));
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        if (
          event.defaultPrevented ||
          dragRef.current?.pointerId !== event.pointerId
        )
          return;
        updateDrag(event.clientX, false);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        if (!event.defaultPrevented) finishDrag(event, false);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        finishDrag(event, true);
      }}
      onDoubleClick={(event) => {
        onDoubleClick?.(event);
        if (event.defaultPrevented) return;
        leafColumns.forEach((column) => column.resetSize());
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || !canResize) return;

        const amount = event.shiftKey ? safeLargeStep : safeStep;
        if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
          event.preventDefault();
          const physicalDirection = event.key === "ArrowRight" ? 1 : -1;
          resizeBy(physicalDirection * resizeDirection * amount);
        }
      }}
    />
  );
}

